import numpy as np
import pandas as pd
from abc import ABC

from server.storage.base import DataReader, RCSBaseWriter
from server.settings import NEURAL_TS_FILENAME, SETTINGS_FILENAME


class NeuralSpec(ABC):

    group_name = "Neural"
    dataset_name = "LFPStream"
    time_name = "Timestamps"


class NeuralReader(NeuralSpec, DataReader):
    """Wrapper class for reading neural data from the HDF5 file"""


class NeuralWriter(NeuralSpec, RCSBaseWriter):
    """Wrapper class for writing new neural data to an HDF5 file"""

    point_shape = (2, 2, 2)
    chunk_spec = (None, )
    dim_names = ['Time', 'Side', 'Location', 'Channel']
    dim_labels = [
        ['Replace', 'With', 'Timestamps'],
        ['Left', 'Right'],
        ['STN', 'M1'],
        ['CH 1', 'CH 2']
    ]

    @classmethod
    def from_sources(cls, left_source, right_source, target_loc, filename=None):
        """Instantiate a NeuralWriter from the raw source files whose locations are provided"""
        filename = NEURAL_TS_FILENAME if filename is None else filename
        return super(NeuralWriter, cls).from_sources(left_source, right_source, target_loc, filename)

    def prep_attributes(self):

        l_attrs = {f'Left {k}': v for k, v in self.left_settings.items()}
        r_attrs = {f'Right {k}': v for k, v in self.right_settings.items()}

        base_attrs = super(NeuralWriter, self).prep_attributes()

        base_attrs.update(**l_attrs)
        base_attrs.update(**r_attrs)

        return base_attrs


